'use strict';
// The look of the Cindy parts (助手面板 v7.2, the second change; Deja, 2026-11-04): cindy-parts.css, generated by
// agent-ui/styles.cjs from the files copied unchanged at 43001ea — Cindy's Tailwind config, tokens and cindy-dark theme —
// with MontClip's colours over them. Reads committed files only (Tailwind is not installed in CI). The page itself, with the
// file on and off, is checked by desktop/cindy-parts-smoke.cjs.
const { test } = require('node:test'), assert = require('node:assert/strict'), fs = require('node:fs'), path = require('node:path');
const read = (f) => fs.readFileSync(path.join(__dirname, '..', f), 'utf8');
const css = read('app/cindy-parts.css'), sources = require('../agent-ui/SOURCES.json');
const { STYLE_ENTRIES, STYLE_FILES } = require('../agent-ui/cindy-resolve.cjs');
// the rules of a CSS file, outside comments: [selector, body]
const rules = (text) => [...text.replace(/\/\*[\s\S]*?\*\//g, '').matchAll(/([^{}@;]+)\{([^{}]*)\}/g)].map((m) => [m[1].trim(), m[2]]);
const SCOPE = ':where([data-cindy-parts], [data-radix-popper-content-wrapper], [data-morph-side], [role="alertdialog"], .modal-scrim)';
const split = (s) => s.split(/,(?![^(]*\))/).map((x) => x.trim());
// every selector of a rule, outside @keyframes (from / to / n%)
const selectors = () => rules(css).flatMap(([s]) => split(s)).filter((s) => !/^(from|to|[\d.]+%)$/.test(s));
// the variable names MontClip's own page uses or sets
const OWN = ['app/style.css', 'app/app.js', 'app/index.html', 'agent-ui/pane.tsx'].map(read).join('\n');
const mine = new Set([...OWN.matchAll(/var\(\s*--([\w-]+)|(?:^|[{;\s'"])--([\w-]+)\s*:|setProperty\(\s*['"]--([\w-]+)/g)].map((m) => m[1] || m[2] || m[3]));
const esc = (n) => n.replace(/[-]/g, '\\-');

test('the page loads it before its own style.css; it is generated, and says from what', () => {
  const html = read('app/index.html');
  assert.ok(html.indexOf('<link rel="stylesheet" href="app/cindy-parts.css">') >= 0);
  assert.ok(html.indexOf('href="app/cindy-parts.css"') < html.indexOf('href="app/style.css"'), "MontClip's own rules come after Cindy's");
  assert.match(css.slice(0, 600), /MontClip generated, agent-ui\/styles\.cjs/);
  assert.match(css.slice(0, 600), /43001eaaa31ef322de9ae148c4051087277d6198/);
  assert.match(css.slice(0, 600), /Tailwind CSS 3\.4\.19 \(MIT/);
  assert.ok(require('../package.json').files.includes('app/'), 'in the npm package (with the page in app/, #281 stage 3)');
});

test("what it is made from was copied unchanged at 43001ea (SOURCES.json parts): Cindy's Tailwind config, tokens and theme", () => {
  const copied = new Set(sources.parts.files.map((f) => f.file));
  for (const f of [...STYLE_ENTRIES, ...STYLE_FILES, 'apps/desktop/src/renderer/components/ui/button.css']) assert.ok(copied.has(f), f);
});

test("Cindy's variables are set inside the parts only, and none of MontClip's names (VV on f3df7db: --muted)", () => {
  const theme = rules(css).find(([s, b]) => s === SCOPE && /--text-primary:/.test(b));
  assert.ok(theme, "Cindy's cindy-dark theme block, on the parts");
  assert.ok([...theme[1].matchAll(/(--[\w-]+)\s*:/g)].length >= 500, 'the whole theme');
  // nothing on :root, html or the page's elements: every rule that sets a variable is inside the parts
  for (const [s, b] of rules(css)) if (/(^|[;{\s])--[\w-]+\s*:/.test(b)) for (const x of split(s)) assert.ok(x.includes(SCOPE), 'a variable set outside the parts: ' + x);
  // style.css's own var(--x) names, as Deja asked: none is set by this file, anywhere; nor read, so a part uses Cindy's copy
  const used = [...read('app/style.css').matchAll(/var\(\s*--([\w-]+)/g)].map((m) => m[1]);
  assert.ok(used.includes('muted') && used.includes('accent') && used.includes('border'));
  for (const n of new Set([...used, ...mine])) {
    assert.doesNotMatch(css, new RegExp('(^|[;{\\s])--' + esc(n) + '\\s*:'), '--' + n + " is MontClip's: set here");
    assert.doesNotMatch(css, new RegExp('var\\(\\s*--' + esc(n) + '(?![\\w-])'), '--' + n + " is MontClip's: read here");
  }
  // Cindy's own values under the --cindy- name (a part's Tailwind colour reads them there, e.g. var(--cindy-chat-input-bg))
  for (const n of ['border', 'accent', 'muted']) assert.ok(css.includes('--cindy-' + n + ':'), n);
  assert.ok(css.includes('var(--cindy-chat-input-bg)'));
  // no copied part reads a renamed one some other way (an inline style, JavaScript): it would find nothing
  const renamed = [...new Set([...css.matchAll(/--cindy-([\w-]+)\s*:/g)].map((m) => m[1]))].filter((n) => mine.has(n));
  assert.ok(renamed.length >= 3);
  const walk = (d) => fs.readdirSync(d, { withFileTypes: true }).flatMap((e) => e.isDirectory() ? walk(path.join(d, e.name)) : [path.join(d, e.name)]);
  const files = [...walk(path.join(__dirname, '../agent-ui/cindy-43001ea/apps/desktop/src/renderer')), ...walk(path.join(__dirname, '../agent-ui/stand-ins'))]
    .filter((f) => /\.(tsx?|cjs)$/.test(f) && !f.includes('__tests__'));
  for (const f of files) {
    const text = fs.readFileSync(f, 'utf8');
    for (const n of renamed) assert.ok(!new RegExp('style=\\{[^}]*var\\(--' + esc(n) + '(?![\\w-])|getPropertyValue\\([\'"]--' + esc(n) + '[\'"]').test(text), n + ' in ' + f);
  }
});

test('every rule applies inside the parts only: no selector, class or element, without the scope (VV on f3df7db)', () => {
  const all = selectors();
  assert.ok(all.length > 900);
  assert.deepEqual(all.filter((s) => !s.includes(SCOPE)), [], 'unscoped selectors');
  // the class names MontClip's page uses too are among them, scoped
  for (const c of ['hidden', 'grid', 'block', 'fixed', 'filter', 'sr-only']) {
    assert.ok(all.some((s) => s === SCOPE + ' .' + c), '.' + c + ' scoped');
    assert.ok(!all.includes('.' + c));
  }
  // the scoped preflight is there: a button has no face of its own inside a part
  assert.ok(all.includes(SCOPE + ' button'), 'button reset, scoped');
  assert.doesNotMatch(css, /(^|\})\s*(:root|html|body)\s*[,{]/, 'no rule for :root, html or body');
});

test("MontClip's colours come last (v7.2 §1): its accent #7b6cff for the focus ring and icons; AA-passing tints for 自动 / Yolo text", () => {
  const own = rules(read('agent-ui/montclip-theme.css'));
  assert.equal(own.length, 1);
  // the file's last rule is montclip-theme.css's, on the parts
  const [sel, root] = rules(css).at(-1);
  assert.equal(sel, SCOPE);
  assert.equal(root.replace(/\s+/g, ''), own[0][1].replace(/\s+/g, ''));
  const v = (n) => new RegExp('--' + n + ':\\s*([^;]+);').exec(root)?.[1].trim();
  assert.equal(v('focus-ring'), '#7b6cff');
  // WCAG AA at 13px regular (QQ on #109): #9b8fff is 5.52 on the hover pill #272727, #ff6b70 5.40;
  // #7b6cff / #e5484d there were 3.86 / 3.82 — they stay for icons and focus rings only (3:1)
  assert.equal(v('perm-auto-selected-text'), '#9b8fff');
  assert.equal(v('perm-bypass-selected-text'), '#ff6b70', "Yolo: MontClip's red hue, lightened to pass AA");
  // white on #6a5bf0 is 4.81:1; white on the old #7b6cff was 3.87
  assert.equal(v('confirm-btn-primary-bg'), '#6a5bf0');
  assert.equal(v('accent-cta-bg-pure'), '#6a5bf0');
  assert.match(read('app/style.css'), /--accent: #7b6cff;/, "MontClip's accent is that one");
});

test('the mode menu has a surface (QQ on #109): --menu-panel-surface on the parts, opaque; the panel rule present', () => {
  // MorphPopover reads var(--menu-panel-surface) for its panel; without it the 计划/手动/自动/Yolo menu is
  // transparent over the timeline. The scoped base rule makes it the opaque --cmd-palette-bg (as on Cindy's win32
  // path; the [data-theme=…] translucent variants never match — MontClip sets no data-theme).
  const base = rules(css).find(([s, b]) => s === SCOPE && /--menu-panel-surface:/.test(b));
  assert.ok(base, '--menu-panel-surface defined on the parts');
  assert.match(base[1], /--menu-panel-surface:\s*var\(--cmd-palette-bg\)/);
  assert.ok(rules(css).some(([s]) => split(s).some((x) => /\[data-menu-surface\]/.test(x) && x.includes(SCOPE))), '[data-menu-surface] rule, scoped');
  // and every variable a rule reads is one the parts set — or runtime-owned (Radix sets --radix-*, Tailwind's shadow
  // internals --tw-*), or read with an explicit fallback (var(--app-font-code, var(--app-font-code-default)))
  const defined = new Set([...css.matchAll(/(^|[;{\s])--([\w-]+)\s*:/g)].map((m) => m[2]));
  const bare = [...css.matchAll(/var\(\s*--([\w-]+)(\s*\))/g)].map((m) => m[1]);
  assert.deepEqual([...new Set(bare)].filter((n) => !defined.has(n) && !/^(radix|tw)-/.test(n)).sort(), [], 'a var the parts read but never set');
});

test('no selector is split at a CSS hex escape (QQ on #109): `\\2c ` ends with a space that is not a combinator', () => {
  // styles.cjs:firstCompoundEnd used to read that space as a descendant combinator and insert SCOPE mid-class
  // (22 rules, e.g. `.hover\:bg-\[var\(--composer-pill-bg\2c:where(…) \#FCFCFC\)\]:hover`)
  for (const s of selectors()) assert.doesNotMatch(s, /\\[0-9a-fA-F]{1,6}:where\(/, s);
  // and the escapes are still there, whole (this guards the guard: the fixture classes exist)
  assert.ok(selectors().filter((s) => /\\[0-9a-fA-F]{1,6}\s/.test(s)).length >= 20, 'escaped class names present');
});
